SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END paid_cohort, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) status_values FROM payments GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END HAVING SUM(amount) > 7600 ORDER BY status_values, paid_cohort LIMIT 1;
